use expect_test::expect;

use super::{
    assert_apropospriate_dark_parity, assert_apropospriate_light_parity,
    assert_apropospriate_theme_parity,
};

#[test]
fn apropospriate_theme_descriptor_records_exact_pin_and_payload() {
    let elisp_form = r##"(let* ((desc
                (cadr (assq 'apropospriate-theme package-alist)))
              (dir (package-desc-dir desc)))
         (list
          (package-version-join (package-desc-version desc))
          (package-desc-reqs desc)
          (package-desc-kind desc)
          (sort
           (mapcar #'file-name-nondirectory
                   (directory-files dir t "^[^.].*"))
           #'string<)))"##;
    let expect = expect![[
        r#"OK ("20251010.121" nil nil ("README-elpa" "apropospriate-dark-theme.el" "apropospriate-dark-theme.elc" "apropospriate-light-theme.el" "apropospriate-light-theme.elc" "apropospriate-theme-autoloads.el" "apropospriate-theme-pkg.el" "apropospriate-theme.el"))"#
    ]];
    assert_apropospriate_theme_parity(elisp_form, expect);
}

#[test]
fn apropospriate_theme_callable_custom_and_group_surface_is_exact() {
    let elisp_form = r##"(list
         (mapcar
          (lambda (symbol)
            (list symbol
                  (help-function-arglist symbol t)
                  (macrop symbol)
                  (commandp symbol)
                  (documentation symbol t)))
          '(apropospriate-with-color-variables
            create-apropospriate-theme))
         (mapcar
          (lambda (symbol)
            (list symbol
                  (default-value symbol)
                  (custom-variable-p symbol)
                  (get symbol 'custom-type)
                  (get symbol 'custom-group)))
          '(apropospriate-mode-line-height
            apropospriate-org-level-resizing))
         (get 'apropospriate 'group-documentation)
         (get 'apropospriate 'custom-group))"##;
    let expect = expect![[
        r#"OK (((apropospriate-with-color-variables (variant &rest body) t nil nil) (create-apropospriate-theme (variant theme-name) nil nil "Create a VARIANT of the theme named THEME-NAME.")) ((apropospriate-mode-line-height 0.95 ((funcall #'#[nil (0.95) #1=(t)])) number nil) (apropospriate-org-level-resizing t ((funcall #'#[nil (t) #1#])) boolean nil)) "Apropospriate theme options." ((apropospriate-mode-line-height custom-variable) (apropospriate-org-level-resizing custom-variable)))"#
    ]];
    assert_apropospriate_theme_parity(elisp_form, expect);
}

#[test]
fn apropospriate_theme_light_palette_binds_every_color_token() {
    let elisp_form = r##"(apropospriate-with-color-variables 'light
         (list
          class variant
          base00 base01 base02 base03
          yellow yellow-1 brown brown-1 orange orange-1
          red red-1 pink pink-1 purple purple-1
          blue blue-1 indigo indigo-1 cyan cyan-1
          teal teal-1 green green-1
          base00-1 base00-2 base00-3
          base00+1 base00+2 base00+3
          light-emphasis light-emphasis-1 light-emphasis-2
          flashing-color highlight-line-color))"##;
    let expect = expect![[
        r##"OK (((class color) (min-colors 89)) light "#F5F5F5" "#90A4AE" "#78909C" "#546E7A" "#F57F17" "#F9A725" "#4E342E" "#6D4C41" "#D84315" "#FF5722" "#D50000" "#FF1744" "#F8BBD0" "#EC407A" "#7E57C2" "#B388FF" "#42A5F5" "#1E88E5" "#5C6BC0" "#9FA8DA" "#0097A7" "#00B8D4" "#26A69A" "#00897B" "#66BB6A" "#558B2F" "#FBFBFB" "#FDFDFD" "#FFFFFF" "#F0F0F0" "#EBEBEB" "#E6E6E6" "#E6E6E6" "#EBEBEB" "#F0F0F0" "#FCE2EB" "#EEEEEE")"##
    ]];
    assert_apropospriate_theme_parity(elisp_form, expect);
}

