#[test]
fn apropospriate_theme_main_load_registers_feature_and_theme_directory_once() {
    let elisp_form = r##"(let* ((source
                (locate-library "apropospriate-theme"))
               (directory
                (file-name-as-directory
                 (file-name-directory source))))
         (load source nil 'nomessage)
         (load source nil 'nomessage)
         (list
          (featurep 'apropospriate-theme)
          (cl-count 'apropospriate-theme features)
          (cl-count directory custom-theme-load-path
                    :test #'equal)
          (member directory custom-theme-load-path)
          (custom-theme-p 'apropospriate-dark)
          (custom-theme-p 'apropospriate-light)))"##;
    let expect = expect![[
        r#"OK (t 1 1 ("[ORACLE-WORKSPACE]/tmp/melpa/package-cache/apropospriate-theme/20251010.121/home/.emacs.d/elpa/apropospriate-theme-20251010.121/" custom-theme-directory t) nil nil)"#
    ]];
    assert_apropospriate_theme_parity(elisp_form, expect);
}

